import hmac
import os
import time

from flask import Blueprint, request

from .errors import problem

bp = Blueprint("webhooks", __name__)

MAX_EVENT_AGE_SECONDS = 300


def _verify_psp_signature():
    """Return an error response if the request is not a valid PSP event, else None."""
    secret = os.environ.get("PSP_WEBHOOK_SECRET")
    if not secret:
        return problem(401, "Invalid signature", "Webhook verification is not configured")

    signature = request.headers.get("Psp-Signature")
    timestamp = request.headers.get("Psp-Timestamp")
    if not signature or not timestamp:
        return problem(401, "Invalid signature", "Missing signature headers")

    try:
        age = time.time() - float(timestamp)
    except ValueError:
        return problem(401, "Invalid signature", "Malformed timestamp")
    if abs(age) > MAX_EVENT_AGE_SECONDS:
        return problem(401, "Invalid signature", "Timestamp outside tolerance")

    expected = hmac.new(
        secret.encode(), request.get_data(), hashlib.sha256
    ).hexdigest()
    if not hmac.compare_digest(expected, signature):
        return problem(401, "Invalid signature", "Signature mismatch")
    return None


@bp.post("/webhooks/psp")
def psp_webhook():
    error = _verify_psp_signature()
    if error is not None:
        return error

    event = request.get_json()
    # TODO: dispatch on event["type"]
    return "", 204
